insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m2.q1', 'm2', 'single', 'm2.1', 'Which layer of a web page decides colours, spacing and fonts?', null, '["HTML","CSS","JavaScript","Git"]'::jsonb, 'Structure, style, behaviour: which one is style?', '1'::jsonb, '["HTML gives the page its structure: what is there, not how it looks.","Correct: CSS controls how everything looks.","JavaScript adds behaviour, like reacting to clicks.","Git tracks versions of your files. It doesn''t style anything."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m2.q2', 'm2', 'single', 'm2.1', 'Spot the bug. Which line breaks this page?', '1  <section id="about">
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m2.q3', 'm2', 'single', 'm2.2', 'What is the best way to mark up the part of your page that lists your projects?', null, '["<div class=\"box3\">","<section id=\"projects\"> with <h2>Projects</h2>","<footer>","<span id=\"p\">"]'::jsonb, 'Use a tag that says what the block is, plus an id for links.', '1'::jsonb, '["It works visually, but nothing says what this block is.","Correct: semantic, linkable with #projects, and the verifier finds it.","A footer is for the bottom of the page, like contact details.","A span is for a few words inside text, not a whole part of the page."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m2.q4', 'm2', 'single', 'm2.2', 'Your nav link is <a href="#skills">Skills</a>. Where does it take the visitor?', null, '["To a page called skills.html","To the element with id=\"skills\" on the same page","To the first <h2> on the page","Nowhere: links need a full URL"]'::jsonb, 'What does the # point at?', '1'::jsonb, '["That would be href=\"skills.html\". A # means a place on the current page.","Correct: # links jump to the element whose id matches.","Links don''t look for headings, they look for a matching id.","A # link works without a full URL."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m2.q5', 'm2', 'order', 'm2.3', 'Put the layers of the CSS box model in order, from the inside out.', null, '["margin","padding","content","border"]'::jsonb, 'Padding is inside the border, margin is outside.', '[2,1,3,0]'::jsonb, '["Content in the middle, then padding inside the border, then the border, then margin outside it."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m2.q6', 'm2', 'single', 'm2.3', 'Your text is squashed against the edge of its card. Which property adds space inside the card?', null, '["margin","padding","border-width","gap"]'::jsonb, 'Inside the border or outside it?', '1'::jsonb, '["Margin is outside the border: it pushes the whole card away from its neighbours.","Correct: padding is the space between the content and the border.","A thicker border is still a line; it doesn''t add breathing room inside.","gap spaces children inside a flex or grid parent, not the text inside a card."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m2.q7', 'm2', 'single', 'm2.3', 'A card has width: 200px; padding: 20px; border: 5px solid. Without box-sizing: border-box, how wide does it look?', null, '["200px","225px","250px","240px"]'::jsonb, 'Add padding and border on both sides.', '2'::jsonb, '["That is only the content. Padding and border are added on top by default.","Only one side of the padding and border was added.","Correct: 200 + 20 + 20 + 5 + 5 = 250px.","The border was left out: 200 + 20 + 20 = 240, plus 5 on each side."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m2.q8', 'm2', 'single', 'm2.4', 'You want a gallery of project cards in rows and columns. Which layout fits best?', null, '["display: grid","display: block","position: absolute on every card","float: left with fixed margins"]'::jsonb, 'Rows and columns at once.', '0'::jsonb, '["Correct: grid lays children out in rows and columns at once.","Block stacks every card on its own line.","You would have to place every card by hand, and it breaks on other screens.","Floats are an old technique and are fragile for layouts."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m2.q9', 'm2', 'single', 'm2.4', 'Where do you put display: flex to line up three skill badges in a row?', null, '["On each badge","On the element that contains the badges","On the <body> only","In the <head>"]'::jsonb, 'Style the parent; children follow.', '1'::jsonb, '["Flex on a badge arranges what is inside that badge, not the badges themselves.","Correct: the layout is set on the parent, and its children follow.","The body would line up all the page''s main blocks, not just the badges.","The head holds information about the page, not visible layout."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m2.q10', 'm2', 'single', 'm2.5', 'Which CSS creates the frosted-glass blur of what is behind a card?', null, '["filter: blur(12px)","opacity: 0.5","backdrop-filter: blur(12px)","box-shadow: 0 0 12px white"]'::jsonb, 'It filters the backdrop.', '2'::jsonb, '["filter blurs the card itself, text included.","opacity fades the whole card and blurs nothing.","Correct: backdrop-filter blurs whatever is behind the element.","A shadow adds a glow around the card; the background stays sharp."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m2.q11', 'm2', 'single', 'm2.6', 'Spot the bug. On a phone this page is tiny and zoomed out. Which line is missing something?', '1  <head>
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m2.q12', 'm2', 'single', 'm2.6', 'What does @media (max-width: 600px) { ... } do?', null, '["Applies the CSS inside only on screens 600px wide or narrower","Limits the whole page to 600px wide","Loads a video player","Applies the CSS only on screens wider than 600px"]'::jsonb, 'max-width means "up to".', '0'::jsonb, '["Correct: the rules inside only apply when the screen is at most 600px wide.","That would be max-width on an element, like main { max-width: 600px }.","Media queries are about screens, not video or audio.","That would be min-width: 601px."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
